import type {System,SavedRating,Average} from './lesson-rating';
import type {Level} from './portal-experience';
export interface CourseLesson {readonly id:string;readonly title:string;readonly description:string;readonly stage:string;readonly stageTitle:string;readonly goal:string;readonly goalKey:string;readonly requires:readonly string[];readonly optional:boolean;readonly challengeReady:boolean;readonly gradeFingerprint:string;readonly musicVersion:string;readonly editionVersion:string;readonly bpm?:number;readonly timeLimit?:number;readonly rating:Average|null}
export interface Course {readonly version:1;readonly policyVersion:1;readonly sha256:string;readonly route:readonly string[];readonly lessons:readonly CourseLesson[];readonly counts:{learning:number;graded:number;sequential:number;practice:number}}
